"""
Installer for composer.py v1.2 — writes the file directly into
groovegen_pilot/, no download folder, no filename mangling.

Usage:
    cd /Users/daniel/Desktop/PhD/groove_gen_project/
    python install_composer_v12.py

Verifies MD5 after install. Backs up any existing composer.py to composer.py.bak.
"""
import base64, gzip, hashlib, sys, shutil
from pathlib import Path

EXPECTED_MD5 = "00320e632fe1cf9a3212b42b9cab713a"
TARGET = Path("groovegen_pilot/composer.py")
BACKUP = Path("groovegen_pilot/composer.py.bak")

BLOB = """

"""

def main() -> int:
    if not Path("groovegen_pilot").is_dir():
        print("ERROR: run this from the groove_gen_project/ repo root.")
        print(f"  cwd: {Path.cwd()}")
        return 1
    data = gzip.decompress(base64.b64decode(BLOB.strip()))
    md5 = hashlib.md5(data).hexdigest()
    if md5 != EXPECTED_MD5:
        print(f"ERROR: MD5 mismatch. expected {EXPECTED_MD5}, got {md5}")
        return 1
    if TARGET.exists():
        BACKUP.write_bytes(TARGET.read_bytes())
        print(f"  backed up existing composer.py -> {BACKUP}")
    TARGET.write_bytes(data)
    print(f"  installed composer.py v1.2 ({len(data)} bytes, MD5 {md5}) -> {TARGET}")
    pyc = Path("groovegen_pilot/__pycache__")
    if pyc.exists():
        shutil.rmtree(pyc)
        print(f"  cleared {pyc}")
    print("")
    print("OK. Verify with:")
    print("  python -c \"import sys; sys.path.insert(0,'groovegen_pilot'); from composer import generate_segment; p=generate_segment('calm',density=0.6,duration_bars=8,seed=42); print('calm:', sum(len(i.notes) for i in p.instruments), '(expect 86)')\"")
    return 0

if __name__ == "__main__":
    sys.exit(main())
